output_text:
[
  {
    "id": "no_cart_single_file_aisles",
    "text": "A cart must not be taken into single-file shelf aisles, i.e. one-cell-wide passages with shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "no_push_north_from_single_file_mouth",
    "text": "It is forbidden to push a cart north from the mouth of a single-file shelf aisle into that aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "singleFileMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "pushNorthIntoSingleFileWithCart": {
          "pre": {
            "and": [
              "singleFileMouth",
              "hasCart",
              "N"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pushNorthIntoSingleFileWithCart"
    }
  },
  {
    "id": "parked_cart_implies_enter_on_foot",
    "text": "If an agent parks a cart at the mouth of a single-file shelf aisle, they are obliged to enter that aisle on foot before leaving.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "singleFileMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "dropCartAtSingleFileMouth": {
          "pre": {
            "and": [
              "singleFileMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "enterSingleFileOnFoot": {
          "pre": {
            "and": [
              "singleFileMouth",
              {
                "not": "hasCart"
              },
              "N"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "dropCartAtSingleFileMouth",
      "discharge": "enterSingleFileOnFoot"
    }
  },
  {
    "id": "retrieve_after_entering_single_file",
    "text": "After entering a single-file shelf aisle without the cart, the agent must later retrieve the cart from a single-file aisle mouth.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "singleFileMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "enterSingleFileOnFoot": {
          "pre": {
            "and": [
              "singleFileMouth",
              {
                "not": "hasCart"
              },
              "N"
            ]
          },
          "post": "singleFileShelfAisle"
        },
        "retrieveCartAtSingleFileMouth": {
          "pre": {
            "and": [
              "singleFileMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterSingleFileOnFoot",
      "discharge": "retrieveCartAtSingleFileMouth"
    }
  },
  {
    "id": "leave_single_file_south_after_interact",
    "text": "After interacting with an item inside a single-file shelf aisle, the agent must leave the aisle by returning south to its mouth.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "singleFileMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "interactInSingleFileOnFoot": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": null
        },
        "exitSingleFileSouthToMouth": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "S"
            ]
          },
          "post": "singleFileMouth"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "interactInSingleFileOnFoot",
      "discharge": "exitSingleFileSouthToMouth"
    }
  },
  {
    "id": "drop_cart_only_at_single_file_mouth",
    "text": "Except for ordinary item interactions, deliberately dropping or parking a cart is allowed only at the mouth of a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "singleFileMouth"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_only_from_bay_or_mouth",
    "text": "Picking up a cart is permitted only at the entrance cart bay or at a single-file aisle mouth where a cart was parked.",
    "abstraction": {
      "state_properties": {
        "cartBay": "at(1,7)",
        "singleFileMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "legalCartPickupPlace": {
          "or": [
            "cartBay",
            "singleFileMouth"
          ]
        }
      },
      "events": {
        "pickUpCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "pickUpCart",
          {
            "not": "legalCartPickupPlace"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_for_accessible_shelf_interactions",
    "text": "When interacting with a cart-accessible shelf area, the agent must have the cart; the only shelf interactions allowed without a cart are in single-file aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartAccessibleShelfArea": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartAccessibleShelfArea",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
